import { useState } from "react";
import { Form } from "./components/form";
import { FormBlockFormElement } from "./form-block.types";
import { convertFormToServiceData } from "./form-block.functions";
import { FormField } from "@/core/helpers/form-builder";
import structure from "@/core/styling/structure.module.less";
import DialogModal from "@/core/components/primitives/dialog-modal/dialog-modal";
import { EventAggregator } from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { EmailService } from "@/core/services";
import { ExistingThemes } from "@/core/types";
import useFocus from "@/core/hooks/use-focus";
import { RichTextType } from "@/core/components/primitives/rich-text/rich-text";

type FormBlockProps = {
  contentfulId?: string;
  title?: string;
  descriptionMarkdown?: {
    childMarkdownRemark: {
      html: string;
    };
  };
  /**
   * @deprecated Use descriptionMarkdown instead
   */
  description?: string;
  recipient: string;
  emailTitle: string;
  labelSendButton: string;
  labelMailHasBeenSentButton: string;
  formCompleted?: string;
  formCompletedNew?: RichTextType;
  formElements: Array<FormBlockFormElement>;
  componentTheme?: ExistingThemes;
};

export const FormBlock = ({
  contentfulId,
  title,
  descriptionMarkdown,
  description,
  recipient,
  emailTitle,
  labelSendButton,
  labelMailHasBeenSentButton,
  formCompleted,
  formCompletedNew,
  formElements,
  componentTheme,
}: FormBlockProps) => {
  const { t } = useTranslation();
  const [focusRef, setFocus] = useFocus<HTMLElement>();

  const [isSendingEmail, setIsSendingEmail] = useState(false);
  const [mailHasBeenSent, setMailHasBeenSent] = useState(false);
  const [showAlertDialog, setShowAlertDialog] = useState(false);

  const hasExactlyOneEmailElement = formElements.filter((element) => element.type === "emailField").length === 1;
  if (!hasExactlyOneEmailElement) {
    console.error("FormBlock must have exactly one emailField");
    return null;
  }

  const internalTitleOfEmailElement = formElements.filter((element) => element.type === "emailField")[0].internalTitle;

  const onSubmit = async (formFields: Map<string, FormField>) => {
    setIsSendingEmail(true);

    const formValuesToSend = convertFormToServiceData(formFields, formElements);
    const requesterEmail = formFields.get(internalTitleOfEmailElement)?.value ?? "";

    try {
      await EmailService.sendGenericFormEmail({
        title: emailTitle,
        formid: "generic",
        requesteremail: requesterEmail,
        requestername: requesterEmail,
        recipient: recipient,
        data: formValuesToSend,
      });

      setIsSendingEmail(false);
      setMailHasBeenSent(true);
    } catch (e) {
      EventAggregator.publish("trackException", {
        exception: e,
        customMessage: "FormBlock onSubmit",
      });
      setShowAlertDialog(true);
      setIsSendingEmail(false);
      setMailHasBeenSent(false);
    }
  };

  function closeDialog() {
    setFocus();
    setShowAlertDialog(false);
  }

  return (
    <section
      ref={focusRef}
      tabIndex={-1}
      className={`
    ${structure.block}
    ${structure.blockFloating}
    ${structure.blockMaxWidthS}`}
      data-contentful-id={contentfulId}
    >
      <Form
        title={title}
        descriptionMarkdown={descriptionMarkdown}
        description={description}
        labelSendButton={labelSendButton}
        labelMailHasBeenSentButton={labelMailHasBeenSentButton}
        formCompleted={formCompleted}
        formCompletedNew={formCompletedNew}
        onSubmit={(data) => {
          onSubmit(data);
        }}
        isSendingEmail={isSendingEmail}
        mailHasBeenSent={mailHasBeenSent}
        formElements={formElements}
        componentTheme={componentTheme}
      />
      {showAlertDialog && (
        <DialogModal
          headingText={t("formSomethingWentWrong")}
          bodyText={t("formCouldNotSendAnswers")}
          primaryButtonText={t("formErrorDialogOkLabel")}
          primaryButtonAction={closeDialog}
          onCloseFunction={closeDialog}
        />
      )}
    </section>
  );
};
