import styles from "./dialog-modal.module.less";
import {
  PrimaryButton,
  PrimaryButtonLink,
  SecondaryButton,
  SecondaryButtonLink,
} from "@/core/components/primitives/parks-button/parks-button";
import { Modal } from "@/core/components/primitives/modal/modal";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { multipleClassNames } from "@/core/helpers";
import { ExistingThemes } from "@/core/types";

export type DialogModalProps = {
  headingText?: string;
  bodyText?: string | JSX.Element;
  primaryButtonText?: string;
  primaryButtonAction?: () => void;
  primaryButtonLink?: string;
  secondaryButtonText?: string;
  secondaryButtonAction?: () => void;
  secondaryButtonLink?: string;
  onCloseFunction: () => void;
  contentfulLabelIds?: {
    headingText?: string;
    bodyText?: string;
    confirmChange?: string;
    cancelChange?: string;
  };
  parentTheme?: ExistingThemes;
};

const DialogModal = ({
  headingText,
  bodyText,
  primaryButtonText,
  primaryButtonAction,
  primaryButtonLink,
  secondaryButtonText,
  secondaryButtonAction,
  secondaryButtonLink,
  onCloseFunction,
  contentfulLabelIds,
  parentTheme,
}: DialogModalProps) => {
  const wrapperElement = useContentContainerRef();

  return (
    <Modal
      portalId={MODAL_PORTAL_ID}
      isOpen={true}
      refWrapperElement={wrapperElement ?? undefined}
      onClose={onCloseFunction}
      modalTitle="modalTitle"
      className={multipleClassNames(parentTheme && `component-theme component-theme-${parentTheme} ${parentTheme}`)}
    >
      <div className={styles.wrapper}>
        <div className={styles.innerWrapper}>
          <div className={styles.textWrapper}>
            {headingText && (
              <h4
                id="modalTitle"
                className={styles.headingText}
                data-contentful-label-id={contentfulLabelIds?.headingText}
              >
                {headingText}
              </h4>
            )}
            {bodyText && (
              <div className={styles.bodyTextWrapper} data-contentful-label-id={contentfulLabelIds?.bodyText}>
                {bodyText}
              </div>
            )}
          </div>
          <div className={styles.buttonWrapper}>
            {primaryButtonText && primaryButtonLink && (
              <span onClick={() => primaryButtonAction && primaryButtonAction()}>
                <PrimaryButtonLink
                  isFullWidth={true}
                  url={primaryButtonLink}
                  label={primaryButtonText}
                  className={styles.acceptButton}
                  data-contentful-label-id={contentfulLabelIds?.confirmChange}
                />
              </span>
            )}
            {primaryButtonText && primaryButtonAction && !primaryButtonLink && (
              <PrimaryButton
                isFullWidth={true}
                onClick={primaryButtonAction}
                label={primaryButtonText}
                className={styles.acceptButton}
                data-contentful-label-id={contentfulLabelIds?.confirmChange}
              />
            )}
            {secondaryButtonText && secondaryButtonLink && (
              <span onClick={() => secondaryButtonAction && secondaryButtonAction()}>
                <SecondaryButtonLink
                  isFullWidth={true}
                  url={secondaryButtonLink}
                  label={secondaryButtonText}
                  complementary={true}
                  className={styles.denyButton}
                  data-contentful-label-id={contentfulLabelIds?.cancelChange}
                />
              </span>
            )}
            {secondaryButtonText && secondaryButtonAction && !secondaryButtonLink && (
              <SecondaryButton
                isFullWidth={true}
                onClick={secondaryButtonAction}
                label={secondaryButtonText}
                complementary={true}
                className={styles.denyButton}
                data-contentful-label-id={contentfulLabelIds?.cancelChange}
              />
            )}
          </div>
        </div>
      </div>
    </Modal>
  );
};

export default DialogModal;
