import { ConferenceBookingFormBody, ContactRequestFormBody, GenericFormBody } from "@/core/types";
import ServiceHelper from "@/core/services/service-helper";

export const EmailService = {
  async sendConferenceBookingEmail(body: ConferenceBookingFormBody) {
    await ServiceHelper.fetchPost("/email/conferencebooking", body);
  },
  async sendContactRequestEmail(body: ContactRequestFormBody) {
    await ServiceHelper.fetchPost("/email/contactrequest", body);
  },
  async sendGenericFormEmail(body: GenericFormBody) {
    await ServiceHelper.fetchPost("/email/genericform", body);
  },
};
